"""Forecast service: prediction ledger + calibration injection."""

import json
import logging
from datetime import datetime, timezone
from typing import Any

from ..db.connection import execute, fetch_all, fetch_one, get_connection
from .prediction_engine import HORIZONS, MODEL_VERSION, generate_forecast

logger = logging.getLogger(__name__)


def _load_calibration_context(ticker: str, sector: str) -> dict[str, Any]:
    """Load signed residuals from audits generated by the current forecast model."""
    audits = fetch_all(
        "SELECT p.horizon, p.predicted_price, a.actual_close "
        "FROM error_audits a JOIN predictions p ON a.prediction_id = p.id "
        "WHERE p.ticker = ? AND p.model_version = ? "
        "AND p.predicted_price > 0 AND a.actual_close > 0 "
        "ORDER BY a.audit_date DESC LIMIT 1000",
        (ticker, MODEL_VERSION),
    )

    residuals: dict[str, list[float]] = {}
    for audit in audits:
        predicted = float(audit["predicted_price"])
        actual = float(audit["actual_close"])
        residuals.setdefault(audit["horizon"], []).append(actual / predicted - 1)
    return {
        "horizons": {
            horizon: {"residuals": values}
            for horizon, values in residuals.items()
        }
    }


def save_market_context_snapshot(
    ticker: str,
    market_context: dict[str, Any],
    news_context: list[dict[str, Any]],
) -> int:
    """Persist the exact context available to a forecast for later backtesting."""
    captured_at = datetime.now(timezone.utc).isoformat(timespec="microseconds").replace(
        "+00:00", "Z"
    )
    context_json = json.dumps(
        {
            "market_context": market_context,
            "news_context": news_context,
        },
        allow_nan=False,
        separators=(",", ":"),
    )
    conn = get_connection()
    try:
        cursor = conn.execute(
            "INSERT INTO market_context_snapshots (ticker, captured_at, context_json) "
            "VALUES (?, ?, ?)",
            (ticker, captured_at, context_json),
        )
        conn.commit()
        return cursor.lastrowid
    finally:
        conn.close()


def save_prediction(forecast: dict[str, Any]) -> int:
    """Write the prediction ledger for all horizons."""
    if not forecast.get("predictions"):
        return 0

    now = datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    inserted = 0
    for h, pred in forecast["predictions"].items():
        params = (
            forecast["ticker"],
            h,
            pred["prediction_date"],
            pred["predicted_price"],
            pred.get("interval_coverage", 0.9),
            pred.get("low", 0),
            pred.get("high", 0),
            pred.get("interval_coverage", 0.9),
            pred.get("interval_method", "unavailable"),
            forecast.get("model_version", "legacy"),
            forecast.get("context_snapshot_id"),
            pred.get("sentiment_score", 0.0),
            pred.get("key_assumptions", ""),
            now,
        )
        query = """
            INSERT OR REPLACE INTO predictions
            (ticker, horizon, prediction_date, predicted_price, confidence_interval,
             low, high, interval_coverage, interval_method, model_version,
             context_snapshot_id, sentiment_score, key_assumptions, created_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
        """
        execute(query, params, fetch=False)
        inserted += 1
    return inserted


def save_error_audit(audit: dict[str, Any]) -> int:
    """Append one audit record to error_audits."""
    params = (
        audit["prediction_id"],
        audit["audit_date"],
        audit["actual_close"],
        audit["absolute_error"],
        audit["percentage_error"],
        1 if audit["directional_correct"] else 0,
        audit.get("notes", ""),
        datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z"),
    )
    query = """
        INSERT INTO error_audits
        (prediction_id, audit_date, actual_close, absolute_error, percentage_error,
         directional_correct, notes, audited_at)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    """
    return execute(query, params, fetch=False)


def upsert_forecast_accuracy(ticker: str, horizon: str, mape: float, hit_rate: float,
                             mean_abs_error: float, sample_size: int) -> int:
    """Upsert into forecast_accuracy table."""
    now = datetime.now(timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    params = (ticker, horizon, mape, hit_rate, mean_abs_error, sample_size, now)
    query = """
        INSERT OR REPLACE INTO forecast_accuracy
        (ticker, horizon, rolling_30d_mape, directional_hit_rate, mean_abs_error,
         sample_size, last_reported_at)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    """
    return execute(query, params, fetch=False)
